package com.example.TuVanSinhVien.controller;

import com.example.TuVanSinhVien.config.CustomUserDetails;
import com.example.TuVanSinhVien.entity.*;
import com.example.TuVanSinhVien.repository.NguoiTuVanRepository;
import com.example.TuVanSinhVien.service.*;
import org.springframework.format.annotation.DateTimeFormat;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.servlet.mvc.support.RedirectAttributes;
import java.time.LocalDateTime;
import java.util.List;

@Controller
@RequestMapping("/advisor")
public class AdvisorController {
    private final NguoiTuVanRepository nguoiTuVanRepo;
    private final TicketService ticketService;
    private final AppointmentService appointmentService;
    private final ChatService chatService;
    private final CatalogService catalogService;
    private final NotificationService notificationService;

    private NguoiTuVan getAdvisorOrThrow(CustomUserDetails userDetails) {
        if (userDetails == null) {
            throw new SecurityException("Vui lòng đăng nhập.");
        }
        return nguoiTuVanRepo.findByTaiKhoan_MaTK(userDetails.getMaTK()).orElseThrow(() -> new IllegalStateException("Không tìm thấy thông tin cố vấn cho tài khoản này."));
    }

    @GetMapping("/dashboard")
    public String dashboard(@AuthenticationPrincipal CustomUserDetails userDetails, Model model) {
        NguoiTuVan cv = getAdvisorOrThrow(userDetails);
        List<YeuCauTuVan> myTickets = ticketService.getAdvisorAssignedTickets(cv.getMaCV());
        List<YeuCauTuVan> queue = ticketService.getDepartmentQueue(cv.getDonVi().getMaDonVi());
        List<LichHenTuVan> appointments = appointmentService.getAdvisorAppointments(cv.getMaCV());
        long pendingAppointments = appointments.stream().filter(a -> "ChoDuyet".equals(a.getTrangThai())).count();
        model.addAttribute("advisor", cv);
        model.addAttribute("assignedTickets", myTickets);
        model.addAttribute("queueTickets", queue);
        model.addAttribute("pendingAppointmentsCount", pendingAppointments);
        model.addAttribute("appointments", appointments.stream().limit(5).toList());
        model.addAttribute("notifications", notificationService.getUserNotifications(cv.getTaiKhoan().getMaTK()).stream().limit(5).toList());
        return "advisor/dashboard";
    }

    @GetMapping("/tickets")
    public String tickets(@AuthenticationPrincipal CustomUserDetails userDetails, Model model) {
        NguoiTuVan cv = getAdvisorOrThrow(userDetails);
        model.addAttribute("advisor", cv);
        model.addAttribute("assignedTickets", ticketService.getAdvisorAssignedTickets(cv.getMaCV()));
        model.addAttribute("queueTickets", ticketService.getDepartmentQueue(cv.getDonVi().getMaDonVi()));
        return "advisor/tickets";
    }

    @PostMapping("/tickets/{id}/claim")
    public String claimTicket(@PathVariable Integer id, @AuthenticationPrincipal CustomUserDetails userDetails, RedirectAttributes redirectAttributes) {
        try {
            NguoiTuVan cv = getAdvisorOrThrow(userDetails);
            ticketService.claimTicket(id, cv);
            redirectAttributes.addFlashAttribute("successMessage", "Bạn đã tiếp nhận phiếu tư vấn #" + id + " thành công!");
            return "redirect:/advisor/tickets/" + id;
        } catch (Exception e) {
            redirectAttributes.addFlashAttribute("errorMessage", e.getMessage());
            return "redirect:/advisor/tickets";
        }
    }

    @GetMapping("/tickets/{id}")
    public String ticketDetail(@PathVariable Integer id, @AuthenticationPrincipal CustomUserDetails userDetails, Model model) {
        NguoiTuVan cv = getAdvisorOrThrow(userDetails);
        YeuCauTuVan ticket;
        try {
            ticket = ticketService.getAdvisorTicket(id, cv);
        } catch (SecurityException e) {
            return "redirect:/advisor/tickets";
        }
        if (ticket == null) {
            return "redirect:/advisor/tickets";
        }
        model.addAttribute("ticket", ticket);
        model.addAttribute("advisor", cv);
        model.addAttribute("mauTraLoiList", catalogService.getMauTraLoiByDonVi(cv.getDonVi().getMaDonVi()));
        model.addAttribute("donViList", catalogService.getAllActiveDonVi());
        model.addAttribute("linhVucList", catalogService.getAllActiveLinhVuc());
        return "advisor/ticket-detail";
    }

    @PostMapping("/tickets/{id}/reply")
    public String replyTicket(@PathVariable Integer id, @AuthenticationPrincipal CustomUserDetails userDetails, @RequestParam String noiDung, @RequestParam(required = false) Boolean deXuatFaq, RedirectAttributes redirectAttributes) {
        try {
            NguoiTuVan cv = getAdvisorOrThrow(userDetails);
            ticketService.replyTicket(id, cv, noiDung, deXuatFaq);
            redirectAttributes.addFlashAttribute("successMessage", "Đã gửi câu trả lời tư vấn thành công!");
        } catch (Exception e) {
            redirectAttributes.addFlashAttribute("errorMessage", e.getMessage());
        }
        return "redirect:/advisor/tickets/" + id;
    }

    @PostMapping("/tickets/{id}/transfer")
    public String transferTicket(@PathVariable Integer id, @AuthenticationPrincipal CustomUserDetails userDetails, @RequestParam Integer maDonViMoi, @RequestParam Integer maLinhVucMoi, @RequestParam String lyDo, RedirectAttributes redirectAttributes) {
        try {
            NguoiTuVan cv = getAdvisorOrThrow(userDetails);
            ticketService.transferTicket(id, maDonViMoi, maLinhVucMoi, lyDo, cv);
            redirectAttributes.addFlashAttribute("successMessage", "Đã chuyển tiếp yêu cầu sang đơn vị mới.");
            return "redirect:/advisor/tickets";
        } catch (Exception e) {
            redirectAttributes.addFlashAttribute("errorMessage", e.getMessage());
            return "redirect:/advisor/tickets/" + id;
        }
    }

    @GetMapping("/slots")
    public String slots(@AuthenticationPrincipal CustomUserDetails userDetails, Model model) {
        NguoiTuVan cv = getAdvisorOrThrow(userDetails);
        model.addAttribute("advisor", cv);
        model.addAttribute("slots", appointmentService.getAdvisorSlots(cv.getMaCV()));
        return "advisor/slots";
    }

    @PostMapping("/slots/new")
    public String createSlot(@AuthenticationPrincipal CustomUserDetails userDetails, @RequestParam @DateTimeFormat(iso = DateTimeFormat.ISO.DATE_TIME) LocalDateTime batDau, @RequestParam Integer thoiLuongPhut, @RequestParam String hinhThuc, @RequestParam String diaDiemLink, RedirectAttributes redirectAttributes) {
        try {
            NguoiTuVan cv = getAdvisorOrThrow(userDetails);
            LocalDateTime ketThuc = batDau.plusMinutes(thoiLuongPhut);
            appointmentService.createSlot(cv, batDau, ketThuc, hinhThuc, diaDiemLink);
            redirectAttributes.addFlashAttribute("successMessage", "Mở khung giờ tư vấn mới thành công!");
        } catch (Exception e) {
            redirectAttributes.addFlashAttribute("errorMessage", e.getMessage());
        }
        return "redirect:/advisor/slots";
    }

    @GetMapping("/appointments")
    public String appointments(@AuthenticationPrincipal CustomUserDetails userDetails, Model model) {
        NguoiTuVan cv = getAdvisorOrThrow(userDetails);
        model.addAttribute("advisor", cv);
        model.addAttribute("appointments", appointmentService.getAdvisorAppointments(cv.getMaCV()));
        return "advisor/appointments";
    }

    @PostMapping("/appointments/{id}/approve")
    public String approveAppointment(@PathVariable Integer id, @AuthenticationPrincipal CustomUserDetails userDetails, @RequestParam String linkHopPhong, RedirectAttributes redirectAttributes) {
        try {
            NguoiTuVan cv = getAdvisorOrThrow(userDetails);
            appointmentService.approveAppointment(id, cv.getMaCV(), linkHopPhong);
            redirectAttributes.addFlashAttribute("successMessage", "Đã phê duyệt lịch hẹn tư vấn!");
        } catch (Exception e) {
            redirectAttributes.addFlashAttribute("errorMessage", e.getMessage());
        }
        return "redirect:/advisor/appointments";
    }

    @PostMapping("/appointments/{id}/reject")
    public String rejectAppointment(@PathVariable Integer id, @AuthenticationPrincipal CustomUserDetails userDetails, @RequestParam String lyDo, RedirectAttributes redirectAttributes) {
        try {
            NguoiTuVan cv = getAdvisorOrThrow(userDetails);
            appointmentService.rejectAppointment(id, cv.getMaCV(), lyDo);
            redirectAttributes.addFlashAttribute("successMessage", "Đã từ chối lịch hẹn.");
        } catch (Exception e) {
            redirectAttributes.addFlashAttribute("errorMessage", e.getMessage());
        }
        return "redirect:/advisor/appointments";
    }

    @PostMapping("/appointments/{id}/complete")
    public String completeAppointment(@PathVariable Integer id, @AuthenticationPrincipal CustomUserDetails userDetails, @RequestParam String ketLuan, RedirectAttributes redirectAttributes) {
        try {
            NguoiTuVan cv = getAdvisorOrThrow(userDetails);
            appointmentService.completeAppointment(id, cv.getMaCV(), ketLuan);
            redirectAttributes.addFlashAttribute("successMessage", "Đã ghi nhận hoàn tất buổi tư vấn.");
        } catch (Exception e) {
            redirectAttributes.addFlashAttribute("errorMessage", e.getMessage());
        }
        return "redirect:/advisor/appointments";
    }

    @GetMapping("/chat")
    public String chatDashboard(@AuthenticationPrincipal CustomUserDetails userDetails, @RequestParam(required = false) Integer sessionId, Model model) {
        NguoiTuVan cv = getAdvisorOrThrow(userDetails);
        model.addAttribute("advisor", cv);
        model.addAttribute("waitingQueue", chatService.getWaitingQueue(cv.getDonVi().getMaDonVi()));
        model.addAttribute("mySessions", chatService.getAdvisorSessions(cv.getMaCV()));
        if (sessionId != null) {
            try {
                PhienChat session = chatService.getAdvisorSession(sessionId, cv);
                if (session.getNguoiTuVan() == null) {
                    chatService.advisorJoinSession(sessionId, cv);
                }
                model.addAttribute("currentSession", session);
                model.addAttribute("messages", chatService.getMessages(sessionId, cv.getTaiKhoan()));
            } catch (RuntimeException e) {
                model.addAttribute("errorMessage", e.getMessage());
            }
        }
        return "advisor/chat";
    }

    @PostMapping("/chat/{sessionId}/send")
    public String sendChatMessage(@PathVariable Integer sessionId, @AuthenticationPrincipal CustomUserDetails userDetails, @RequestParam String noiDung, RedirectAttributes redirectAttributes) {
        try {
            NguoiTuVan cv = getAdvisorOrThrow(userDetails);
            chatService.sendMessage(sessionId, cv.getTaiKhoan(), noiDung, "VanBan");
        } catch (Exception e) {
            redirectAttributes.addFlashAttribute("errorMessage", e.getMessage());
        }
        return "redirect:/advisor/chat?sessionId=" + sessionId;
    }

    @java.lang.SuppressWarnings("all")
    @lombok.Generated
    public AdvisorController(final NguoiTuVanRepository nguoiTuVanRepo, final TicketService ticketService, final AppointmentService appointmentService, final ChatService chatService, final CatalogService catalogService, final NotificationService notificationService) {
        this.nguoiTuVanRepo = nguoiTuVanRepo;
        this.ticketService = ticketService;
        this.appointmentService = appointmentService;
        this.chatService = chatService;
        this.catalogService = catalogService;
        this.notificationService = notificationService;
    }
}
